  "quiz": [
    {
      "id": "q1",
      "q": "红漆薄棺里那副给甄家骏配阴亲的骨殖，生前是谁？",
      "options": [
        {
          "key": "A",
          "text": "外乡买来的无主女骨"
        },
        {
          "key": "B",
          "text": "何纸生早夭的女儿"
        },
        {
          "key": "C",
          "text": "鬼七娘的女儿阿莲"
        },
        {
          "key": "D",
          "text": "甄家早年病故的童养媳"
        }
      ],
      "answer": "C",
      "clue": "yq_gui_3",
      "explain": "鬼七娘枕下的长命锁錾着民国二年七月初七生，与纸轿上庚帖里新娘的生辰、戚晚晴枕套里结拜红纸上的生辰一致；薄棺骨殖脚上的莲花银脚镯，也正是阿莲的。"
    },
    {
      "id": "q2",
      "q": "新娘骨殖颈下那枚錾着骏字的青玉坠，原本是谁送的？",
      "options": [
        {
          "key": "A",
          "text": "甄崇山"
        },
        {
          "key": "B",
          "text": "甄家骏"
        },
        {
          "key": "C",
          "text": "甄家祺"
        },
        {
          "key": "D",
          "text": "张引魂"
        }
      ],
      "answer": "B",
      "clue": "yq_ct_1",
      "explain": "玉坠背面錾着一个骏字；阿莲生前与大少爷甄家骏相好，这枚青玉坠是甄家骏送给她、她天天贴身戴着的。"
    },
    {
      "id": "q3",
      "q": "何纸生的儿子何小树，五年前是怎么没的？",
      "options": [
        {
          "key": "A",
          "text": "给甄记桐油行撑船，在青浪滩翻了船"
        },
        {
          "key": "B",
          "text": "赶夜路摔下了山崖"
        },
        {
          "key": "C",
          "text": "染上时疫病故"
        },
        {
          "key": "D",
          "text": "在山里被土匪劫杀"
        }
      ],
      "answer": "A",
      "clue": "yq_he_4",
      "explain": "何纸生工具箱夹层里的字据写着：甄记桐油行，船工何小树，青浪滩覆船，赏银五元，概不另偿。"
    },
    {
      "id": "q4",
      "q": "甄家骏三个月前是怎么没的？",
      "options": [
        {
          "key": "A",
          "text": "夜里打水坠井"
        },
        {
          "key": "B",
          "text": "突发急病"
        },
        {
          "key": "C",
          "text": "在寨前河落水"
        },
        {
          "key": "D",
          "text": "进山遇匪"
        }
      ],
      "answer": "C",
      "clue": "yq_ct_3",
      "explain": "祠堂家谱里，甄家骏名下记着民国二十五年四月初九殁于寨前河；甄家祺抽屉里那封写给哥哥的信，也提到那天哥哥在水里朝他喊。"
    },
    {
      "id": "q5",
      "q": "戚晚晴和阿莲是什么关系？",
      "options": [
        {
          "key": "A",
          "text": "亲姐妹"
        },
        {
          "key": "B",
          "text": "拜过的干姐妹"
        },
        {
          "key": "C",
          "text": "表姐妹"
        },
        {
          "key": "D",
          "text": "素不相识"
        }
      ],
      "answer": "B",
      "clue": "yq_qi_3",
      "explain": "戚晚晴枕套里那张红纸并排写着两人的生辰，各按着指印，纸角写着结拜二字。"
    },
    {
      "id": "q6",
      "q": "张引魂是凭什么找到后山乱葬岗那座坟的？",
      "options": [
        {
          "key": "A",
          "text": "鬼七娘给他指的路"
        },
        {
          "key": "B",
          "text": "甄崇山亲笔写的字条"
        },
        {
          "key": "C",
          "text": "何纸生画的地图"
        },
        {
          "key": "D",
          "text": "他自己在乱葬岗随手挑的"
        }
      ],
      "answer": "B",
      "clue": "yq_zhang_4",
      "explain": "张引魂枕芯里的字条写着后山乱葬岗、枫树底下、坟头木牌写莲字者，落款一个山字，正是甄崇山的亲笔。"
    }
  ],
